cards.solution:
function tunggu(ms: number): Promise<void> {
  return new Promise((selesai) => setTimeout(selesai, ms));
}
async function ambilHarga(kode: string): Promise<number> {
  await tunggu(100);
  return kode === "P01" ? 18000 : 12000;
}
async function totalKeranjang(kode: string[]): Promise<number> {
  const harga = await Promise.all(kode.map(ambilHarga));
  return harga.reduce((a, b) => a + b, 0);
}
console.log(await totalKeranjang(["P01", "P02", "P01"]));
